WITH filtered AS (SELECT id, customer_id, store_id, order_date, channel, amount, shipping_fee, CASE WHEN channel IN ('mobile', 'store') THEN 'Group A' ELSE 'Other' END AS channel_group FROM orders WHERE channel IS NOT DISTINCT FROM 'store' AND order_date > DATE '2023-04-26') SELECT id, customer_id, store_id, shipping_fee, channel_group, SUM(amount) OVER w_part AS running_sum_amount, COUNT(amount) OVER w_part AS running_count_amount, MAX(amount) OVER w_part AS running_max_amount FROM filtered WINDOW w_part AS (PARTITION BY store_id, customer_id ORDER BY order_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
